/**
 * Translation handler - orchestrates translation operations
 * Integrates with the routing handler to perform Chat→Response and Response→Chat translations
 */

import type { FastifyInstance } from 'fastify';
import { translateChatToResponse, isChatCompletionsRequest } from '../translation/index.js';
import {
  logTranslation,
  logUnknownFields,
  createTranslationLogEntry
} from '../translation/utils/translation-logger.js';
import type { ResponseApiRequest } from '../translation/types.js';

/**
 * Result of a translation handler operation
 */
export interface TranslationHandlerResult {
  success: boolean;
  translated?: ResponseApiRequest | Record<string, unknown>;
  error?: string;
}

/**
 * Handles Chat Completions → Response API request translation
 * Orchestrates utilities for performance monitoring, logging, and field handling
 *
 * @param logger Fastify logger instance
 * @param requestId Request identifier for correlation
 * @param request The Chat Completions request to translate
 * @returns TranslationHandlerResult with translated output and metrics
 */
export function handleChatToResponseTranslation(
  logger: FastifyInstance['log'],
  requestId: string,
  request: unknown
): TranslationHandlerResult {
  // Validate that this is a Chat Completions request
  if (!isChatCompletionsRequest(request)) {
    logger.warn({
      action: 'translation_invalid_request',
      requestId,
      reason: 'Request does not match Chat Completions format'
    });

    return {
      success: false,
      error: 'Request does not match Chat Completions format'
    };
  }

  try {
    // Perform translation
    const translationResult = translateChatToResponse(request, { requestId });

    if (!translationResult.success) {
      // Translation failed
      const logEntry = createTranslationLogEntry(
        requestId,
        'chat_to_response',
        'translate',
        [],
        false,
        translationResult.error
      );

      logTranslation(logger, logEntry);

      return {
        success: false,
        error: translationResult.error
      };
    }

    // Log unknown fields if detected
    if (translationResult.unknownFields.length > 0) {
      logUnknownFields(
        logger,
        requestId,
        'chat_to_response',
        translationResult.unknownFields
      );
    }

    // Log translation completion with duration
    const logEntry = createTranslationLogEntry(
      requestId,
      'chat_to_response',
      'translate',
      translationResult.unknownFields,
      true
    );

    logTranslation(logger, logEntry);

    // Log multi-turn detection if applicable
    if (translationResult.multi_turn_detected) {
      logger.info({
        action: 'multi_turn_conversation_detected',
        requestId,
        direction: 'chat_to_response',
        message: 'Multi-turn conversation detected; full message history passed through (state management in Epic 4)'
      });
    }

    return {
      success: true,
      translated: translationResult.translated
    };
  } catch (error) {
    logger.error({
      action: 'translation_error',
      requestId,
      error: error instanceof Error ? error.message : String(error)
    });

    return {
      success: false,
      error: error instanceof Error ? error.message : 'Unknown error during translation'
    };
  }
}

import type { FastifyRequest, FastifyReply } from 'fastify';
import { Router } from '../routing/router.js';
import { ModelMapper } from '../routing/model-mapper.js';
import { createPassThroughHandler } from './pass-through.handler.js';
import { handleChatToResponseTranslation } from './translation.handler.js';
import type { AdapterConfig } from '../config/types.js';
import { validateJsonDepth } from '../validation/json-depth-validator.js';
import { isValidationError } from '../types/validation-errors.js';
import { formatValidationError } from './error-formatter.js';

/**
 * Routing handler - determines whether to use pass-through or translation
 * Entry point for both /v1/responses and /v1/chat/completions endpoints
 */

export function createRoutingHandler(config: AdapterConfig) {
  const modelMapper = new ModelMapper(config.modelMapping);
  const router = new Router(modelMapper);
  
  // Create pass-through handlers once for reuse
  const responsesHandler = createPassThroughHandler('responses', { config });
  const chatCompletionsHandler = createPassThroughHandler('chat/completions', { config });

  return async (request: FastifyRequest, reply: FastifyReply) => {
    try {
      // Step 1: Validate JSON depth (must happen after JSON parsing, before routing)
      validateJsonDepth(request.body, config.maxJsonDepth);

      // Determine endpoint from path
      let endpoint: string;
      let passThroughHandler: ReturnType<typeof createPassThroughHandler>;
      
      if (request.url.includes('/v1/responses')) {
        endpoint = 'responses';
        passThroughHandler = responsesHandler;
      } else if (request.url.includes('/v1/chat/completions')) {
        endpoint = 'chat/completions';
        passThroughHandler = chatCompletionsHandler;
      } else {
        return reply.code(404).send({
          error: 'Not Found',
          message: 'Unknown endpoint'
        });
      }

      // Step 2: Make routing decision (includes model validation)
      const routingResult = router.routingDecision(request.url, request.body);

      request.log.info({
        action: 'routing_decision',
        endpoint,
        model: routingResult.model,
        source_format: routingResult.sourceFormat,
        target_format: routingResult.targetFormat,
        decision: routingResult.decision
      });

      // Route based on decision
      if (routingResult.decision === 'pass-through') {
        // Forward to pass-through handler (reuse pre-created handler)
        return passThroughHandler(request, reply);
      } else {
        // Translation required - invoke translation handler for Chat→Response
        if (
          routingResult.sourceFormat === 'chat_completions' &&
          routingResult.targetFormat === 'response'
        ) {
          // Perform translation
          const translationResult = handleChatToResponseTranslation(
            request.log,
            request.id,
            request.body
          );

          if (!translationResult.success) {
            request.log.warn({
              action: 'translation_failed',
              endpoint,
              model: routingResult.model,
              error: translationResult.error
            });

            return reply.code(400).send({
              error: 'Translation Error',
              message: translationResult.error,
              requestId: request.id
            });
          }

          // Create a modified request with the translated payload
          const translatedRequest = {
            ...request,
            body: translationResult.translated
          };

          // Forward translated request to pass-through handler
          request.log.debug({
            action: 'translation_completed',
            endpoint,
            model: routingResult.model
          });

          // Forward to pass-through with translated body
          return passThroughHandler(translatedRequest, reply);
        } else {
          // Other translation directions not yet implemented
          request.log.warn({
            action: 'translation_not_implemented',
            endpoint,
            source: routingResult.sourceFormat,
            target: routingResult.targetFormat,
            message: `Translation from ${routingResult.sourceFormat} to ${routingResult.targetFormat} not yet implemented`
          });

          return reply.code(501).send({
            error: 'Not Implemented',
            message: `Translation from ${routingResult.sourceFormat} to ${routingResult.targetFormat} not yet implemented`,
            sourceFormat: routingResult.sourceFormat,
            targetFormat: routingResult.targetFormat
          });
        }
      }
    } catch (error) {
      // Handle validation/routing errors
      request.log.error({
        action: 'routing_error',
        error: error instanceof Error ? error.message : String(error)
      });

      // Handle ValidationError with standardized error format
      if (isValidationError(error)) {
        const errorResponse = formatValidationError(error, request.id);
        return reply.code(400).send(errorResponse);
      }

      // Handle other errors
      const errorMessage = error instanceof Error ? error.message : String(error);

      return reply.code(400).send({
        error: 'Bad Request',
        message: errorMessage,
        requestId: request.id
      });
    }
  };
}

/**
 * Translation types and interfaces
 */

/**
 * Supported translation directions
 */
export type TranslationDirection = 
  | 'chat_to_response'
  | 'response_to_chat'
  | 'chat_to_response_response'
  | 'response_to_chat_response';

/**
 * Translation mode indicates whether we're translating or passing through
 */
export type TranslationMode = 'translate' | 'pass_through';

/**
 * Result of unknown field detection
 */
export interface UnknownFieldsResult {
  unknownFields: string[];
  cleanedPayload: Record<string, unknown>;
}

/**
 * Structured translation log entry
 */
export interface TranslationLogEntry {
  requestId: string;
  translationDirection: TranslationDirection;
  mode: TranslationMode;
  unknownFields: string[];
  timestamp: string;
  success: boolean;
  error?: string;
}

/**
 * Round-trip test result
 */
export interface RoundTripTestResult {
  success: boolean;
  original: unknown;
  translated: unknown;
  backTranslated: unknown;
  differences: string[];
  semanticEquivalence: {
    model: boolean;
    content: boolean;
    parameters: boolean;
  };
}

/**
 * Chat Completions request format
 */
export interface ChatCompletionsRequest {
  model: string;
  messages: Array<{
    role: string;
    content: string;
  }>;
  temperature?: number;
  max_tokens?: number;
  top_p?: number;
  frequency_penalty?: number;
  presence_penalty?: number;
  n?: number;
  stream?: boolean;
  tools?: Array<Record<string, unknown>>;
  tool_choice?: string | Record<string, unknown>;
  response_format?: Record<string, unknown>;
  metadata?: Record<string, unknown>;
  [key: string]: unknown;
}

/**
 * Response API request format
 */
export interface ResponseApiRequest {
  model: string;
  input?: string;
  instructions?: string;
  temperature?: number;
  max_output_tokens?: number;
  top_p?: number;
  stream?: boolean;
  tools?: Array<Record<string, unknown>>;
  tool_choice?: string | Record<string, unknown>;
  text?: {
    format?: string;
  };
  metadata?: Record<string, unknown>;
  [key: string]: unknown;
}

/**
 * Translation context with metadata
 */
export interface TranslationContext {
  requestId: string;
  direction: TranslationDirection;
  mode: TranslationMode;
  startTimeNs: bigint;
}

/**
 * Translation logging utility
 * Provides structured logging for translation operations
 */

import type { FastifyInstance } from 'fastify';
import type { TranslationLogEntry, TranslationDirection } from '../types.js';

/**
 * Logs a translation operation with structured information
 * @param logger Fastify logger instance
 * @param entry Translation log entry
 */
export function logTranslation(logger: FastifyInstance['log'], entry: TranslationLogEntry): void {
  if (entry.success) {
    logger.info({
      action: 'translation_completed',
      requestId: entry.requestId,
      translationDirection: entry.translationDirection,
      mode: entry.mode,
      unknownFieldsCount: entry.unknownFields.length,
      unknownFields: entry.unknownFields,
      timestamp: entry.timestamp
    }, `Translation completed: ${entry.translationDirection}`);
  } else {
    logger.error({
      action: 'translation_failed',
      requestId: entry.requestId,
      translationDirection: entry.translationDirection,
      mode: entry.mode,
      error: entry.error,
      timestamp: entry.timestamp
    }, `Translation failed: ${entry.error}`);
  }
}

/**
 * Logs when unknown fields are detected during translation
 * @param logger Fastify logger instance
 * @param requestId Request identifier
 * @param direction Translation direction
 * @param unknownFields List of unknown field names
 */
export function logUnknownFields(
  logger: FastifyInstance['log'],
  requestId: string,
  direction: TranslationDirection,
  unknownFields: string[]
): void {
  if (unknownFields.length > 0) {
    logger.debug({
      action: 'unknown_fields_detected',
      requestId,
      direction,
      count: unknownFields.length,
      fields: unknownFields
    }, `Unknown fields detected in ${direction} translation: ${unknownFields.join(', ')}`);
  }
}

/**
 * Logs a translation error with context
 * @param logger Fastify logger instance
 * @param requestId Request identifier
 * @param direction Translation direction
 * @param error Error message or Error object
 */
export function logTranslationError(
  logger: FastifyInstance['log'],
  requestId: string,
  direction: TranslationDirection,
  error: string | Error
): void {
  const errorMessage = error instanceof Error ? error.message : error;
  
  logger.error({
    action: 'translation_error',
    requestId,
    direction,
    error: errorMessage
  }, `Translation error in ${direction}: ${errorMessage}`);
}

/**
 * Creates a translation log entry from operation data
 * @param requestId Request identifier
 * @param direction Translation direction
 * @param mode Translation mode (translate or pass_through)
 * @param durationMs Duration in milliseconds
 * @param unknownFields List of unknown fields
 * @param success Whether translation was successful
 * @param error Optional error message if failed
 * @returns TranslationLogEntry
 */
export function createTranslationLogEntry(
  requestId: string,
  direction: TranslationDirection,
  mode: 'translate' | 'pass_through',
  unknownFields: string[],
  success: boolean,
  error?: string
): TranslationLogEntry {
  return {
    requestId,
    translationDirection: direction,
    mode,
    unknownFields,
    timestamp: new Date().toISOString(),
    success,
    error
  };
}

/**
 * Translation module exports
 * Provides access to all translation utilities and translation functions
 */

// Utilities
export * from './utils/unknown-fields.js';
export * from './utils/translation-logger.js';
export * from './utils/round-trip-tester.js';

// Types
export * from './types.js';

// Chat → Response translation
export * from './chat-to-response/types.js';
export * from './chat-to-response/request.js';

// Main exports for convenience
export { translateChatToResponse, isChatCompletionsRequest } from './chat-to-response/request.js';

