      });

      expect(response.statusCode).toBe(400);
      const body = JSON.parse(response.body);
      expect(body.requestId).toBeDefined();
    });
  });

  describe('Request Validation', () => {
    it('should accept all required fields', async () => {
      const validRequest = {
        model: 'gpt-4',
